const fs = require('fs');
const input = fs.readFileSync(0, 'utf8');
let pos = 0;

function nextInt() {
  while (pos < input.length && input.charCodeAt(pos) <= 32) pos++;
  let value = 0;
  while (pos < input.length) {
    const c = input.charCodeAt(pos);
    if (c < 48 || c > 57) break;
    value = value * 10 + c - 48;
    pos++;
  }
  return value;
}

const S = nextInt();
const T = nextInt();
const adjacency = new Uint8Array(S * S);

for (let i = 0; i < T; i++) {
  const x = nextInt() - 1;
  const y = nextInt() - 1;
  adjacency[x * S + y] = 1;
  adjacency[y * S + x] = 1;
}

const P = nextInt();
let possible = 0;

for (let i = 0; i < P; i++) {
  const N = nextInt();
  let previous = nextInt() - 1;
  let valid = true;

  for (let j = 1; j < N; j++) {
    const current = nextInt() - 1;
    if (!adjacency[previous * S + current]) valid = false;
    previous = current;
  }

  if (valid) possible++;
}

console.log(possible.toString());
